def test_journal_get_accepts_scalar_title(httpx_mock, client):
    httpx_mock.add_response(json=fixture("journal_get.json"))
    journal = client.journals.get("20493630")
    assert httpx_mock.get_requests()[0].url.path == "/v1/journals/2049-3630"
    assert journal.primary_title == "IEEE Transactions on Image Processing"
    assert journal.counts is not None
    assert journal.counts.total_dois == 13411
    assert journal.issn == ["1057-7149", "1941-0042"]


